using System.Text;using System.Globalization;using UnityEngine;
namespace MultiFPS {
[CreateAssetMenu(menuName="Rift/Session chat tuning")]public sealed class RiftSessionChatTuning:ScriptableObject {
 public float LocalRadius=35,NpcCooldown=15,InviteLifetime=30;public int MaximumCharacters=200,MaximumMemoryLines=60;public float MemorySeconds=120,BubbleSeconds=5;public int Burst=4;public float MessagesPerSecond=.8f;[Range(2,4)]public int MaximumPartyMembers=4;
 static RiftSessionChatTuning cached;public static RiftSessionChatTuning Load{get{if(!cached)cached=Resources.Load<RiftSessionChatTuning>("RiftSessionChatTuning");if(!cached)cached=CreateInstance<RiftSessionChatTuning>();return cached;}}
 public float NpcDelay=>Mathf.Clamp(float.IsFinite(NpcCooldown)?NpcCooldown:15,2,120);public float InviteSeconds=>Mathf.Clamp(float.IsFinite(InviteLifetime)?InviteLifetime:30,5,60);public float BufferSeconds=>Mathf.Clamp(float.IsFinite(MemorySeconds)?MemorySeconds:120,10,600);public float BubbleLifetime=>Mathf.Clamp(float.IsFinite(BubbleSeconds)?BubbleSeconds:5,2,8);
 public float Radius=>Mathf.Clamp(float.IsFinite(LocalRadius)?LocalRadius:35,2,100);public int Characters=>Mathf.Clamp(MaximumCharacters,20,300);public int PartyLimit=>Mathf.Clamp(MaximumPartyMembers,2,4);
 public static string Plain(string value,int limit){if(string.IsNullOrEmpty(value))return "";var b=new StringBuilder(Mathf.Min(value.Length,limit));bool tag=false,space=false;foreach(char c in value){if(c=='<'){tag=true;continue;}if(c=='>'){tag=false;continue;}if(tag||char.IsControl(c)||char.GetUnicodeCategory(c)==UnicodeCategory.Format)continue;if(char.IsWhiteSpace(c)){if(b.Length>0)space=true;continue;}if(space&&b.Length<limit)b.Append(' ');space=false;if(b.Length>=limit)break;b.Append(c);}if(b.Length>0&&char.IsHighSurrogate(b[b.Length-1]))b.Length--;return b.ToString().Trim();}
}
public sealed class RiftChatRateGate {double last;float tokens;bool initialized;public bool Take(double now,int burst,float rate){burst=Mathf.Clamp(burst,1,8);rate=Mathf.Clamp(float.IsFinite(rate)?rate:.8f,.1f,3);if(!initialized){tokens=burst;last=now;initialized=true;}tokens=Mathf.Min(burst,tokens+(float)System.Math.Max(0,now-last)*rate);last=now;if(tokens<1)return false;tokens-=1;return true;}}
public readonly struct RiftChatLine {public readonly uint Actor;public readonly string Npc,Name,Text;public readonly Vector3 Position;public readonly byte Channel;public RiftChatLine(uint actor,string npc,string name,string text,Vector3 position,byte channel){Actor=actor;Npc=npc;Name=name;Text=text;Position=position;Channel=channel;}}
}
